predicate IsBalanced(g: string) 
    reads g
{
    var count := 0;
    var i := 0;
    while i < g.Length
        invariant 0 <= i <= g.Length
        invariant count >= 0
    {
        if g[i] == '(' {
            count := count + 1;
        } else if g[i] == ')' {
            count := count - 1;
        }
        i := i + 1;
    }
    count == 0
}

